function detect(samples, events, now, H) {
  var W = 180000;
  if (!H.covers(samples, W)) return null;
  var s = H.since(samples, now - W);
  if (!s || s.length < 120) return null;
  var minX = 1e9, maxX = -1e9, minZ = 1e9, maxZ = -1e9, changes = 0, prev = '';
  for (var i = 0; i < s.length; i++) {
    var p = s[i];
    if (p.x < minX) minX = p.x;
    if (p.x > maxX) maxX = p.x;
    if (p.z < minZ) minZ = p.z;
    if (p.z > maxZ) maxZ = p.z;
    var st = p.st || '';
    if (st && st !== prev) { if (prev) changes++; prev = st; }
  }
  var dx = maxX - minX, dz = maxZ - minZ;
  if (dx > 3 || dz > 3) return null;
  var fails = 0, works = 0;
  var evs = H.evSince(events, now - W) || [];
  for (var j = 0; j < evs.length; j++) {
    if (evs[j].k === 'fail') fails++;
    else if (evs[j].k === 'dig' || evs[j].k === 'place') works++;
  }
  if (changes < 4 || fails < 3 || works > 2) return null;
  return { sev: 'med', msg: 'autopilot changed step ' + changes + 'x in 3 min inside a ' + dx.toFixed(1) + 'x' + dz.toFixed(1) + ' block spot with ' + fails + ' fails', data: { changes: changes, fails: fails, works: works } };
}
